#!/usr/bin/env python3
"""
to_gpx_converter.py - Universal GPS Trajectory to GPX Converter for Map Matching Datasets.

Automatically detects and converts multiple benchmark map matching trajectory formats to standard GPX 1.1:
  1. Newson-Krumm dataset (data/eval/mapmatching/gps_data.txt)
     - Tab/whitespace separated with Date, Time, Latitude, Longitude.
  2. GISCup Contest dataset (data/eval/mapmatching/GisContestTrainingData/input/*.txt)
     - Comma-separated: elapsed_time_seconds, latitude, longitude.
  3. Melbourne GPS Track & Ground Truth (data/eval/mapmatching/melbourne/gps_track.txt, groundtruth.txt)
     - gps_track.txt: count header, space-separated timestamp, lat, lon.
     - groundtruth.txt: count header, road segment IDs resolved using complete-osm-map/streets.txt.
  4. Hanwen Hu / Shanghai dataset (data/eval/mapmatching/Shanghai/track/*.csv)
     - CSV with locatetime (epoch ms), lat, lon, speed, direction.
  5. Generic CSV/TSV with lat/lon coordinate columns.

Usage:
  python3 to_gpx_converter.py <input_file_or_dir> [-o <output_file_or_dir>]
"""

import sys
import os
import re
import csv
import glob
import argparse
from datetime import datetime, timezone
from xml.sax.saxutils import escape


class DatasetType:
    NEWSON_KRUMM = "Newson-Krumm Dataset (Date/Time tab-separated)"
    GISCUP = "GISCup Contest Dataset (Comma-separated time_sec, lat, lon)"
    MELBOURNE_GPS = "Melbourne GPS Track (Count header with timestamp lat lon)"
    MELBOURNE_GROUNDTRUTH = "Melbourne Ground Truth (Count header with segment IDs)"
    HANWENHU_SHANGHAI = "Hanwen Hu / Shanghai Track (CSV with locatetime ms, lat, lon)"
    GENERIC_CSV = "Generic CSV/TSV Coordinate Table"
    UNKNOWN = "Unknown Format"


class TrackPoint:
    def __init__(self, lat: float, lon: float, time_iso: str = None, speed: float = None, elevation: float = None):
        self.lat = lat
        self.lon = lon
        self.time_iso = time_iso
        self.speed = speed
        self.elevation = elevation


def detect_dataset_type(file_path: str) -> tuple[str, list[str]]:
    """Inspects the first few lines of the file to auto-detect the dataset type."""
    sample_lines = []
    try:
        with open(file_path, "r", encoding="utf-8-sig", errors="replace") as f:
            for _ in range(15):
                line = f.readline()
                if not line:
                    break
                s = line.strip()
                if s:
                    sample_lines.append(s)
    except Exception as e:
        return DatasetType.UNKNOWN, []

    if not sample_lines:
        return DatasetType.UNKNOWN, []

    first_line = sample_lines[0].lower()

    # 1. Newson-Krumm: Header contains date/time/latitude/longitude
    if "date" in first_line and ("lat" in first_line or "time" in first_line):
        return DatasetType.NEWSON_KRUMM, sample_lines

    # Or check if data line matches Newson Krumm format: DD-Mon-YYYY HH:MM:SS
    for line in sample_lines[:5]:
        parts = line.split()
        if len(parts) >= 4 and re.match(r"^\d{1,2}-[A-Za-z]{3}-\d{4}$", parts[0]):
            return DatasetType.NEWSON_KRUMM, sample_lines

    # 2. Hanwen Hu / Shanghai CSV: Header contains locatetime and lat/lon
    if "locatetime" in first_line and ("lat" in first_line or "lon" in first_line):
        return DatasetType.HANWENHU_SHANGHAI, sample_lines

    # 3. Melbourne format: First line is a single integer (point count)
    if len(sample_lines) >= 2 and sample_lines[0].isdigit():
        line2_parts = sample_lines[1].split()
        # If line 2 has: <10-digit unix timestamp> <lat> <lon>
        if len(line2_parts) >= 3 and line2_parts[0].isdigit() and len(line2_parts[0]) >= 9:
            try:
                float(line2_parts[1])
                float(line2_parts[2])
                return DatasetType.MELBOURNE_GPS, sample_lines
            except ValueError:
                pass
        # If line 2 is a single integer (segment ID)
        if len(line2_parts) == 1 and line2_parts[0].isdigit():
            return DatasetType.MELBOURNE_GROUNDTRUTH, sample_lines

    # 4. GISCup Contest: comma separated 3 columns (timeSec, lat, lon) with no text header
    comma_parts = sample_lines[0].split(",")
    if len(comma_parts) >= 3:
        try:
            float(comma_parts[0])
            lat = float(comma_parts[1])
            lon = float(comma_parts[2])
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return DatasetType.GISCUP, sample_lines
        except ValueError:
            pass

    # 5. Generic CSV with lat/lon headers
    if any(k in first_line for k in ["lat", "latitude"]) and any(k in first_line for k in ["lon", "lng", "longitude"]):
        return DatasetType.GENERIC_CSV, sample_lines

    return DatasetType.UNKNOWN, sample_lines


def print_progress(current: int, total: int, step_pct: int = 10):
    """Prints conversion progress in percentage increments."""
    if total <= 0:
        return
    pct = int((current / total) * 100)
    # Print at step intervals or on completion
    prev_pct = int(((current - 1) / total) * 100) if current > 0 else 0
    if pct != prev_pct and (pct % step_pct == 0 or pct == 100):
        print(f"  [PROGRESS] Converting to GPX: {pct:3d}% ({current:,}/{total:,} points)")


def parse_newson_krumm(file_path: str) -> list[TrackPoint]:
    """Parses Newson-Krumm dataset (DD-Mon-YYYY HH:MM:SS lat lon)."""
    points = []
    with open(file_path, "r", encoding="utf-8-sig", errors="replace") as f:
        lines = [line.strip() for line in f if line.strip()]

    data_lines = [l for l in lines if not l.lower().startswith("date")]
    total = len(data_lines)

    for i, line in enumerate(data_lines):
        parts = line.split()
        if len(parts) >= 4:
            date_str, time_str, lat_str, lon_str = parts[0], parts[1], parts[2], parts[3]
            try:
                dt = datetime.strptime(f"{date_str} {time_str}", "%d-%b-%Y %H:%M:%S").replace(tzinfo=timezone.utc)
                iso_time = dt.strftime("%Y-%m-%dT%H:%M:%SZ")
                lat, lon = float(lat_str), float(lon_str)
                points.append(TrackPoint(lat=lat, lon=lon, time_iso=iso_time))
            except ValueError:
                continue
        print_progress(i + 1, total)

    return points


def parse_giscup(file_path: str) -> list[TrackPoint]:
    """Parses GISCup dataset (elapsed_seconds, lat, lon)."""
    points = []
    with open(file_path, "r", encoding="utf-8-sig", errors="replace") as f:
        lines = [line.strip() for line in f if line.strip()]

    total = len(lines)
    base_time = datetime(2026, 1, 1, 0, 0, 0, tzinfo=timezone.utc).timestamp()

    for i, line in enumerate(lines):
        parts = [p.strip() for p in line.split(",")]
        if len(parts) >= 3:
            try:
                t_sec = float(parts[0])
                lat = float(parts[1])
                lon = float(parts[2])
                dt = datetime.fromtimestamp(base_time + t_sec, tz=timezone.utc)
                iso_time = dt.strftime("%Y-%m-%dT%H:%M:%SZ")
                points.append(TrackPoint(lat=lat, lon=lon, time_iso=iso_time))
            except ValueError:
                continue
        print_progress(i + 1, total)

    return points


def parse_melbourne_gps(file_path: str) -> list[TrackPoint]:
    """Parses Melbourne GPS track (unix_timestamp_sec lat lon)."""
    points = []
    with open(file_path, "r", encoding="utf-8-sig", errors="replace") as f:
        lines = [line.strip() for line in f if line.strip()]

    data_lines = lines[1:] if lines and lines[0].isdigit() else lines
    total = len(data_lines)

    for i, line in enumerate(data_lines):
        parts = line.split()
        if len(parts) >= 3:
            try:
                ts = int(parts[0])
                lat = float(parts[1])
                lon = float(parts[2])
                dt = datetime.fromtimestamp(ts, tz=timezone.utc)
                iso_time = dt.strftime("%Y-%m-%dT%H:%M:%SZ")
                points.append(TrackPoint(lat=lat, lon=lon, time_iso=iso_time))
            except ValueError:
                continue
        print_progress(i + 1, total)

    return points


def parse_melbourne_groundtruth(file_path: str) -> list[TrackPoint]:
    """Parses Melbourne Ground Truth segment IDs using complete-osm-map/streets.txt."""
    dir_path = os.path.dirname(file_path)
    search_paths = [
        os.path.join(dir_path, "complete-osm-map", "streets.txt"),
        os.path.join(dir_path, "streets.txt"),
        os.path.join(dir_path, "..", "melbourne", "complete-osm-map", "streets.txt"),
        os.path.join(os.getcwd(), "data", "eval", "mapmatching", "melbourne", "complete-osm-map", "streets.txt")
    ]
    streets_file = None
    for p in search_paths:
        if os.path.isfile(p):
            streets_file = p
            break

    if not streets_file:
        # Fallback to checking adjacent gps_track.txt
        fallback_gps = os.path.join(dir_path, "gps_track.txt")
        if os.path.isfile(fallback_gps):
            print(f"  [NOTICE] streets.txt not found. Using adjacent {fallback_gps} for GPS coordinates.")
            return parse_melbourne_gps(fallback_gps)
        raise FileNotFoundError(
            f"Could not locate Melbourne complete-osm-map/streets.txt to resolve segment IDs from {file_path}."
        )

    print(f"  [INFO] Resolving road segment geometries via {streets_file}")
    streets = {}
    with open(streets_file, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) >= 7:
                try:
                    eid = int(parts[0])
                    s_lon, s_lat = float(parts[2]), float(parts[3])
                    e_lon, e_lat = float(parts[5]), float(parts[6])
                    streets[eid] = ((s_lat, s_lon), (e_lat, e_lon))
                except ValueError:
                    continue

    with open(file_path, "r", encoding="utf-8", errors="replace") as f:
        lines = [line.strip() for line in f if line.strip()]

    segment_ids = lines[1:] if lines and lines[0].isdigit() else lines
    total = len(segment_ids)

    base_time = datetime(2013, 10, 12, 18, 0, 0, tzinfo=timezone.utc).timestamp()
    points = []
    curr_time_sec = base_time

    for i, sid_str in enumerate(segment_ids):
        try:
            sid = int(sid_str)
            if sid in streets:
                (s_lat, s_lon), (e_lat, e_lon) = streets[sid]
                # Start coord
                if not points or (abs(points[-1].lat - s_lat) > 1e-6 or abs(points[-1].lon - s_lon) > 1e-6):
                    dt_s = datetime.fromtimestamp(curr_time_sec, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                    points.append(TrackPoint(lat=s_lat, lon=s_lon, time_iso=dt_s))
                    curr_time_sec += 2
                # End coord
                dt_e = datetime.fromtimestamp(curr_time_sec, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                points.append(TrackPoint(lat=e_lat, lon=e_lon, time_iso=dt_e))
                curr_time_sec += 2
        except ValueError:
            continue
        print_progress(i + 1, total)

    return points


def parse_hanwenhu_shanghai(file_path: str) -> list[TrackPoint]:
    """Parses Hanwen Hu / Shanghai CSV track (locatetime ms, lat, lon, speed)."""
    points = []
    with open(file_path, "r", encoding="utf-8-sig", errors="replace") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    total = len(rows)
    for i, row in enumerate(rows):
        try:
            lat = float(row.get("lat", 0))
            lon = float(row.get("lon", 0))
            locatetime = row.get("locatetime")
            speed = float(row.get("speed", 0)) if row.get("speed") else None

            iso_time = None
            if locatetime:
                ms = float(locatetime)
                dt = datetime.fromtimestamp(ms / 1000.0, tz=timezone.utc)
                iso_time = dt.strftime("%Y-%m-%dT%H:%M:%SZ")

            points.append(TrackPoint(lat=lat, lon=lon, time_iso=iso_time, speed=speed))
        except (ValueError, TypeError):
            continue
        print_progress(i + 1, total)

    return points


def parse_generic_csv(file_path: str) -> list[TrackPoint]:
    """Parses a generic CSV/TSV table with latitude and longitude columns."""
    points = []
    with open(file_path, "r", encoding="utf-8-sig", errors="replace") as f:
        sample = f.read(4096)
        f.seek(0)
        delimiter = "\t" if "\t" in sample else ","
        reader = csv.DictReader(f, delimiter=delimiter)
        rows = list(reader)

    if not rows or not reader.fieldnames:
        return []

    # Identify lat / lon / time columns
    lat_col = next((c for c in reader.fieldnames if c.lower() in ["lat", "latitude", "y"]), None)
    lon_col = next((c for c in reader.fieldnames if c.lower() in ["lon", "lng", "longitude", "x"]), None)
    time_col = next((c for c in reader.fieldnames if c.lower() in ["time", "timestamp", "datetime", "locatetime"]), None)

    if not lat_col or not lon_col:
        return []

    total = len(rows)
    for i, row in enumerate(rows):
        try:
            lat = float(row[lat_col])
            lon = float(row[lon_col])
            iso_time = None
            if time_col and row.get(time_col):
                val = row[time_col].strip()
                if val.isdigit() and len(val) >= 12:  # ms epoch
                    iso_time = datetime.fromtimestamp(int(val) / 1000.0, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                elif val.isdigit() and len(val) >= 9:  # sec epoch
                    iso_time = datetime.fromtimestamp(int(val), tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                else:
                    iso_time = val

            points.append(TrackPoint(lat=lat, lon=lon, time_iso=iso_time))
        except (ValueError, KeyError):
            continue
        print_progress(i + 1, total)

    return points


def write_gpx(points: list[TrackPoint], output_path: str, track_name: str = "Trajectory"):
    """Writes the track points to a standard GPX 1.1 file."""
    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        f.write('<?xml version="1.0" encoding="UTF-8"?>\n')
        f.write(
            '<gpx version="1.1" creator="Navigatorx to_gpx_converter.py" '
            'xmlns="http://www.topografix.com/GPX/1/1" '
            'xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" '
            'xsi:schemaLocation="http://www.topografix.com/GPX/1/1 '
            'http://www.topografix.com/GPX/1/1/gpx.xsd">\n'
        )
        f.write(f'  <trk>\n    <name>{escape(track_name)}</name>\n    <trkseg>\n')

        for pt in points:
            f.write(f'      <trkpt lat="{pt.lat:.7f}" lon="{pt.lon:.7f}">\n')
            if pt.time_iso:
                f.write(f'        <time>{escape(pt.time_iso)}</time>\n')
            if pt.speed is not None:
                f.write(f'        <speed>{pt.speed:.2f}</speed>\n')
            f.write('      </trkpt>\n')

        f.write('    </trkseg>\n  </trk>\n</gpx>\n')


def convert_file(input_file: str, output_file: str = None) -> bool:
    """Processes a single file, auto-detects its type, and exports to GPX."""
    if not os.path.isfile(input_file):
        print(f"[ERROR] Input file not found: {input_file}", file=sys.stderr)
        return False

    if not output_file:
        stem, _ = os.path.splitext(input_file)
        output_file = stem + ".gpx"

    print(f"\n========================================================")
    print(f"[FILE] {input_file}")
    dataset_type, _ = detect_dataset_type(input_file)
    print(f"[TYPE] Detected: {dataset_type}")

    if dataset_type == DatasetType.NEWSON_KRUMM:
        points = parse_newson_krumm(input_file)
    elif dataset_type == DatasetType.GISCUP:
        points = parse_giscup(input_file)
    elif dataset_type == DatasetType.MELBOURNE_GPS:
        points = parse_melbourne_gps(input_file)
    elif dataset_type == DatasetType.MELBOURNE_GROUNDTRUTH:
        points = parse_melbourne_groundtruth(input_file)
    elif dataset_type == DatasetType.HANWENHU_SHANGHAI:
        points = parse_hanwenhu_shanghai(input_file)
    elif dataset_type == DatasetType.GENERIC_CSV:
        points = parse_generic_csv(input_file)
    else:
        print(f"[ERROR] Unable to determine dataset format for: {input_file}", file=sys.stderr)
        return False

    if not points:
        print(f"[WARNING] No valid trackpoints extracted from {input_file}")
        return False

    track_name = os.path.splitext(os.path.basename(input_file))[0]
    write_gpx(points, output_file, track_name=track_name)
    print(f"[SUCCESS] Wrote {len(points):,} trackpoints -> {output_file}")
    return True


def main():
    parser = argparse.ArgumentParser(
        description="Convert GPS trajectory datasets (Newson-Krumm, GISCup, Melbourne, Shanghai) to GPX format."
    )
    parser.add_argument("input", help="Path to input file, directory, or wildcard pattern (e.g. data/*.csv)")
    parser.add_argument("-o", "--output", help="Output .gpx file or directory destination", default=None)
    args = parser.parse_args()

    # Expand globs or directory
    if os.path.isdir(args.input):
        files = []
        for ext in ("*.txt", "*.csv", "*.dat"):
            files.extend(glob.glob(os.path.join(args.input, ext)))
            files.extend(glob.glob(os.path.join(args.input, "**", ext), recursive=True))
        files = sorted(list(set(files)))
    elif any(c in args.input for c in ["*", "?", "["]):
        files = sorted(glob.glob(args.input))
    else:
        files = [args.input]

    if not files:
        print(f"[ERROR] No matching files found for: {args.input}", file=sys.stderr)
        sys.exit(1)

    print(f"[START] Processing {len(files)} file(s)...")
    success_count = 0

    for f in files:
        if args.output and (os.path.isdir(args.output) or len(files) > 1):
            os.makedirs(args.output, exist_ok=True)
            stem = os.path.splitext(os.path.basename(f))[0]
            out_file = os.path.join(args.output, stem + ".gpx")
        else:
            out_file = args.output

        if convert_file(f, out_file):
            success_count += 1

    print(f"\n========================================================")
    print(f"[DONE] Successfully converted {success_count}/{len(files)} files to GPX format.")


if __name__ == "__main__":
    main()
